I'll use `Badge` for role and status. Next, the shared badges component, which is used by both the list and detail pages.

```tsx src/components/MemberBadges.tsx
import { Badge } from "@once-ui-system/core";
import { type Role, type Status, roleScheme, statusScheme } from "@/lib/data";

/**
 * Badge has no colour scheme prop, so the scheme is applied through
 * on-background / background tokens on the badge itself.
 */
export function RoleBadge({ role }: { role: Role }) {
  const scheme = roleScheme[role];
  return (
    <Badge
      effect={false}
      background={`${scheme}-alpha-weak`}
      onBackground={`${scheme}-strong`}
      border={`${scheme}-alpha-medium`}
      paddingX="8"
      paddingY="4"
      textVariant="label-default-xs"
    >
      {role}
    </Badge>
  );
}

export function StatusBadge({ status }: { status: Status }) {
  const scheme = statusScheme[status];
  return (
    <Badge
      effect={false}
      icon={status === "Active" ? "check" : status === "Invited" ? "mail" : "lock"}
      background={`${scheme}-alpha-weak`}
      onBackground={`${scheme}-strong`}
      border={`${scheme}-alpha-medium`}
      paddingX="8"
      paddingY="4"
      textVariant="label-default-xs"
    >
      {status}
    </Badge>
  );
}
```

Now the main client component, with search, filter, actions and the invite dialog.

Badge's `border` accepts a Colors value, so the badge styling is type-safe. One adjustment: the template literal `${scheme}-alpha-weak` has to resolve to a `Colors` union member, which holds because the schemes are narrowed literals. Now the main client component.

```tsx src/components/TeamClient.tsx
"use client";

import {
  Avatar,
  Button,
  Column,
  DropdownWrapper,
  Heading,
  IconButton,
  Input,
  Option,
  Row,
  Select,
  Text,
  Textarea,
  Dialog,
  useToast,
} from "@once-ui-system/core";
import Link from "next/link";
import { useMemo, useState } from "react";
import {
  type Member,
  type Role,
  formatDate,
  getInitials,
  invitableRoles,
  isValidEmail,
  members as initialMembers,
  roles,
} from "@/lib/data";
import { RoleBadge, StatusBadge } from "./MemberBadges";

type InviteErrors = { email?: string; role?: string };

const roleFilterOptions = [
  { value: "all", label: "All roles" },
  ...roles.map((r) => ({ value: r, label: r })),
];

const inviteRoleOptions = invitableRoles.map((r) => ({ value: r, label: r }));

export function TeamClient() {
  const { addToast } = useToast();
  const [people, setPeople] = useState<Member[]>(initialMembers);
  const [query, setQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState("all");

  const [inviteOpen, setInviteOpen] = useState(false);
  const [email, setEmail] = useState("");
  const [inviteRole, setInviteRole] = useState("");
  const [message, setMessage] = useState("");
  const [errors, setErrors] = useState<InviteErrors>({});

  const [roleTarget, setRoleTarget] = useState<Member | null>(null);
  const [newRole, setNewRole] = useState("");
  const [removeTarget, setRemoveTarget] = useState<Member | null>(null);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return people.filter((p) => {
      if (roleFilter !== "all" && p.role !== roleFilter) return false;
      if (!q) return true;
      return p.name.toLowerCase().includes(q) || p.email.toLowerCase().includes(q);
    });
  }, [people, query, roleFilter]);

  const filtersActive = query.trim() !== "" || roleFilter !== "all";

  function resetInvite() {
    setEmail("");
    setInviteRole("");
    setMessage("");
    setErrors({});
  }

  function closeInvite() {
    setInviteOpen(false);
    resetInvite();
  }

  function submitInvite(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const next: InviteErrors = {};
    const trimmed = email.trim();
    if (!trimmed) next.email = "Enter an email address.";
    else if (!isValidEmail(trimmed)) next.email = "Enter a valid email address, like name@company.com.";
    if (!inviteRole) next.role = "Choose a role for the new member.";
    setErrors(next);
    if (Object.keys(next).length > 0) return;

    if (people.some((p) => p.email.toLowerCase() === trimmed.toLowerCase())) {
      setErrors({ email: "This person is already on the team." });
      return;
    }

    const local = trimmed.split("@")[0] ?? trimmed;
    const name = local
      .split(/[._-]+/)
      .filter(Boolean)
      .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
      .join(" ");

    const created: Member = {
      id: `m-${String(people.length + 1).padStart(2, "0")}`,
      name: name || trimmed,
      email: trimmed,
      role: inviteRole as Role,
      status: "Invited",
      joined: null,
    };
    setPeople((prev) => [...prev, created]);
    addToast({ variant: "success", message: `Invitation sent to ${trimmed}.` });
    closeInvite();
  }

  function confirmRole() {
    if (!roleTarget || !newRole) return;
    setPeople((prev) =>
      prev.map((p) => (p.id === roleTarget.id ? { ...p, role: newRole as Role } : p)),
    );
    addToast({ variant: "success", message: `${roleTarget.name} is now ${newRole}.` });
    setRoleTarget(null);
  }

  function confirmRemove() {
    if (!removeTarget) return;
    setPeople((prev) => prev.filter((p) => p.id !== removeTarget.id));
    addToast({ variant: "success", message: `${removeTarget.name} was removed from the team.` });
    setRemoveTarget(null);
  }

  function resend(member: Member) {
    addToast({ variant: "success", message: `Invitation re-sent to ${member.email}.` });
  }

  function handleAction(member: Member, action: string) {
    if (action === "role") {
      setNewRole(member.role);
      setRoleTarget(member);
    } else if (action === "resend") {
      resend(member);
    } else if (action === "remove") {
      setRemoveTarget(member);
    }
  }

  return (
    <Column as="main" id="main" fillWidth horizontal="center" paddingY="48" paddingX="24" s={{ paddingX: "16", paddingY: "24" }}>
      <Column maxWidth="l" gap="24">
        <Row
          fillWidth
          horizontal="between"
          vertical="end"
          gap="16"
          s={{ direction: "column", horizontal: "start", vertical: "start" }}
        >
          <Column gap="8">
            <Text variant="label-default-s" onBackground="brand-medium">
              Lumen · Acme Labs
            </Text>
            <Heading as="h1" variant="display-strong-xs">
              Team
            </Heading>
            <Text variant="body-default-s" onBackground="neutral-weak">
              Manage who can view dashboards, triage issues and change settings in this workspace.
            </Text>
          </Column>
          <Button prefixIcon="plus" onClick={() => setInviteOpen(true)}>
            Invite member
          </Button>
        </Row>

        <Row fillWidth gap="12" s={{ direction: "column" }}>
          <Column flex={2} fillWidth>
            <Input
              id="member-search"
              label="Search members"
              placeholder="Search by name or email"
              type="search"
              size="s"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              prefix={<span aria-hidden="true" />}
            />
          </Column>
          <Column flex={1} fillWidth>
            <Select
              id="role-filter"
              label="Filter by role"
              size="s"
              options={roleFilterOptions}
              value={roleFilter}
              onSelect={(value) => setRoleFilter(Array.isArray(value) ? (value[0] ?? "all") : value)}
            />
          </Column>
        </Row>

        <Text variant="body-default-xs" onBackground="neutral-weak" aria-live="polite" role="status">
          {visible.length} of {people.length} {people.length === 1 ? "member" : "members"} shown
        </Text>

        <Column background="surface" border radius="l" overflow="hidden">
          <div style={{ overflowX: "auto" }}>
            <table
              style={{
                width: "100%",
                borderCollapse: "collapse",
                minWidth: "40rem",
              }}
            >
              <caption style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)", whiteSpace: "nowrap" }}>
                Team members, with role and status
              </caption>
              <thead>
                <tr style={{ textAlign: "left" }}>
                  {["Member", "Role", "Status", "Actions"].map((h) => (
                    <th
                      key={h}
                      scope="col"
                      style={{
                        padding: "var(--static-space-12) var(--static-space-16)",
                        borderBottom: "1px solid var(--neutral-alpha-medium)",
                        textAlign: h === "Actions" ? "right" : "left",
                      }}
                    >
                      <Text variant="label-default-xs" onBackground="neutral-weak">
                        {h === "Actions" ? <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>Actions</span> : h}
                        {h === "Actions" ? <span aria-hidden="true">&nbsp;</span> : null}
                      </Text>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {visible.map((member) => (
                  <tr key={member.id} style={{ borderBottom: "1px solid var(--neutral-alpha-weak)" }}>
