                    <td style={{ padding: "var(--static-space-12) var(--static-space-16)" }}>
                      <StatusBadge status={member.status} />
                    </td>
                    <td style={{ padding: "var(--static-space-12) var(--static-space-16)", textAlign: "right" }}>
                      <Row horizontal="end">
                        <DropdownWrapper
                          placement="bottom-end"
                          onSelect={(value) => handleAction(member, value)}
                          trigger={
                            <IconButton
                              icon="moreHorizontal"
                              variant="tertiary"
                              size="s"
                              ariaLabel={`Actions for ${member.name}`}
                            />
                          }
                          dropdown={
                            <Column padding="4" gap="2" minWidth={12}>
                              <Option value="role" label="Change role" />
                              {member.status === "Invited" && (
                                <Option value="resend" label="Resend invite" />
