                </Button>
              )}
            </Column>
          )}
        </Column>
      </Column>

      <Dialog
        open={inviteOpen}
        onClose={closeInvite}
        title="Invite a member"
        description="They'll get an email with a link to join your Lumen workspace."
        footer={
          <Row gap="8" horizontal="end" fillWidth>
            <Button variant="tertiary" onClick={closeInvite}>
              Cancel
            </Button>
            <Button type="submit" form="invite-form" prefixIcon="send">
              Send invite
            </Button>
          </Row>
        }
      >
        <form id="invite-form" onSubmit={submitInvite} noValidate>
          <Column gap="16" paddingTop="8">
            <Input
              id="invite-email"
              label="Email address"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              error={Boolean(errors.email)}
              errorMessage={errors.email}
              aria-required="true"
              aria-invalid={Boolean(errors.email)}
              autoComplete="off"
            />
            <Select
              id="invite-role"
              label="Role"
              options={inviteRoleOptions}
              value={inviteRole}
              onSelect={(value) => {
                setInviteRole(Array.isArray(value) ? (value[0] ?? "") : value);
                setErrors((prev) => ({ ...prev, role: undefined }));
              }}
              error={Boolean(errors.role)}
              errorMessage={errors.role}
            />
            <Textarea
              id="invite-message"
              label="Message (optional)"
              lines={3}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              description="Add a short note, like which project they'll work on."
            />
          </Column>
        </form>
      </Dialog>

      <Dialog
        open={roleTarget !== null}
        onClose={() => setRoleTarget(null)}
