                {member.role}
              </Text>
            </Column>
            <Column gap="4">
              <Text as="dt" variant="label-default-xs" onBackground="neutral-weak">
                Status
              </Text>
              <Text as="dd" variant="body-default-s" style={{ margin: 0 }}>
                {member.status}
              </Text>
            </Column>
            <Column gap="4">
              <Text as="dt" variant="label-default-xs" onBackground="neutral-weak">
