                  s={{ direction: "column", gap: "4" }}
                >
                  <Text variant="body-default-s">{item.text}</Text>
                  <Text variant="body-default-xs" onBackground="neutral-weak">
                    {item.when}
                  </Text>
                </Row>
              ))}
            </Column>
          )}
        </Column>
      </Column>
    </Column>
  );
}
